source=source.replace('__OPTIONS__',options).replace('__THREE__',(ROOT/'vendor/three-0.160.1.min.js').read_text().replace('</script','<\\/script')).replace('__DATA__',data).replace('__SPECS__',json.dumps(specs,ensure_ascii=False))
